package testdata

import (
	_ "embed"
	"encoding/json"
	"net/http"
	"net/url"
	"strings"
	"sync"
	"time"
)

// IBKR OAuth reference fixtures (feature 249). vectors.json is generated by ibkr/gen_vectors.py from
// the ibind reference client; never hand-edit it, and regenerate it whenever a PEM changes.
var (
	//go:embed ibkr/signature_key.pem
	IBKRSignatureKeyPEM string
	//go:embed ibkr/encryption_key.pem
	IBKREncryptionKeyPEM string
	//go:embed ibkr/dhparam.pem
	IBKRDHParamPEM string
	//go:embed ibkr/vectors.json
	ibkrVectorsJSON []byte
)

type IBKRVectors struct {
	Meta struct {
		IbindSHA  string `json:"ibind_sha"`
		Generator string `json:"generator"`
	} `json:"meta"`
	Inputs struct {
		BaseURL           string   `json:"base_url"`
		Realm             string   `json:"realm"`
		ConsumerKey       string   `json:"consumer_key"`
		AccessToken       string   `json:"access_token"`
		AccessTokenSecret string   `json:"access_token_secret"`
		Nonces            []string `json:"nonces"`
		Timestamp         string   `json:"timestamp"`
		DHPrimeHex        string   `json:"dh_prime_hex"`
		DHGenerator       int      `json:"dh_generator"`
		DHRandomHex       string   `json:"dh_random_hex"`
	} `json:"inputs"`
	LSTRequest struct {
		Method                 string `json:"method"`
		URL                    string `json:"url"`
		Nonce                  string `json:"nonce"`
		Prepend                string `json:"prepend"`
		DiffieHellmanChallenge string `json:"diffie_hellman_challenge"`
		BaseString             string `json:"base_string"`
		OAuthSignature         string `json:"oauth_signature"`
		Authorization          string `json:"authorization"`
	} `json:"lst_request"`
	LSTReply struct {
		DiffieHellmanResponse        string `json:"diffie_hellman_response"`
		LiveSessionTokenExpiration   int64  `json:"live_session_token_expiration"`
		LiveSessionTokenSignature    string `json:"live_session_token_signature"`
		BadLiveSessionTokenSignature string `json:"bad_live_session_token_signature"`
		LiveSessionToken             string `json:"live_session_token"`
	} `json:"lst_reply"`
	Requests []IBKRRequestVector `json:"requests"`
	Decrypt  struct {
		CiphertextB64         string `json:"ciphertext_b64"`
		PlaintextHex          string `json:"plaintext_hex"`
		WrongKeyCiphertextB64 string `json:"wrong_key_ciphertext_b64"`
	} `json:"decrypt"`
	DHCases []IBKRDHCase `json:"dh_cases"`
}

// IBKRRequestVector is one LST-signed regular request; Params are the query params ibind signed over.
type IBKRRequestVector struct {
	Name               string            `json:"name"`
	Method             string            `json:"method"`
	URL                string            `json:"url"`
	Params             map[string]string `json:"params"`
	Nonce              string            `json:"nonce"`
	BaseString         string            `json:"base_string"`
	OAuthSignature     string            `json:"oauth_signature"`
	Authorization      string            `json:"authorization"`
	LegacySignatureB64 string            `json:"legacy_signature_b64"`
}

type IBKRDHCase struct {
	Name                  string `json:"name"`
	DHServerBHex          string `json:"dh_server_b_hex"`
	DiffieHellmanResponse string `json:"diffie_hellman_response"`
	KBitlen               int    `json:"k_bitlen"`
	LiveSessionToken      string `json:"live_session_token"`
}

var (
	ibkrVectorsOnce sync.Once
	ibkrVectors     IBKRVectors
)

// MustIBKRVectors decodes vectors.json once; callers must not mutate the returned value.
func MustIBKRVectors() *IBKRVectors {
	ibkrVectorsOnce.Do(func() {
		if err := json.Unmarshal(ibkrVectorsJSON, &ibkrVectors); err != nil {
			panic("testdata: decode ibkr/vectors.json: " + err.Error())
		}
	})
	return &ibkrVectors
}

// IBKR auth endpoint path suffixes served by IBKRAuthHandler; matched by suffix so a base-URL path prefix
// such as /v1/api is tolerated.
const (
	IBKRLSTPath  = "/oauth/live_session_token"
	IBKRInitPath = "/iserver/auth/ssodh/init"
)

// IBKRLSTReplyJSON is the vector (b) live_session_token reply carrying the given signature.
func IBKRLSTReplyJSON(signature string) string {
	r := MustIBKRVectors().LSTReply
	b, _ := json.Marshal(map[string]any{
		"diffie_hellman_response":       r.DiffieHellmanResponse,
		"live_session_token_expiration": r.LiveSessionTokenExpiration,
		"live_session_token_signature":  signature,
	})
	return string(b)
}

// IBKRInitReplyJSON is an ssodh/init reply with the given flags.
func IBKRInitReplyJSON(authenticated, competing bool) string {
	b, _ := json.Marshal(map[string]bool{"authenticated": authenticated, "competing": competing, "connected": true})
	return string(b)
}

// IBKRAuthOverride scripts one auth route. A zero Status and empty Body keep the default reply; Delay and
// Block (each bounded by the request context) hold the reply back.
type IBKRAuthOverride struct {
	Status int
	Body   string
	Delay  time.Duration
	Block  <-chan struct{}
}

// IBKRRecordedRequest is one request seen by IBKRAuthHandler.
type IBKRRecordedRequest struct {
	Method        string
	PathQuery     string
	Authorization string
}

// IBKRAuthHandler replays the IBKR LST handshake and ssodh/init from the ibind vectors and forwards every
// other path to Next. With Strict set, an oauth_signature that differs from the vector for (method,
// path+query, nonce) is answered 401.
type IBKRAuthHandler struct {
	Next   http.Handler
	Strict bool

	mu        sync.Mutex
	overrides map[string]IBKRAuthOverride
	requests  []IBKRRecordedRequest
}

// SetOverride replaces the scripted reply for IBKRLSTPath or IBKRInitPath; a zero value restores the default.
func (h *IBKRAuthHandler) SetOverride(path string, o IBKRAuthOverride) {
	h.mu.Lock()
	defer h.mu.Unlock()
	if h.overrides == nil {
		h.overrides = map[string]IBKRAuthOverride{}
	}
	h.overrides[path] = o
}

// Requests returns a copy of the recorded requests, in arrival order.
func (h *IBKRAuthHandler) Requests() []IBKRRecordedRequest {
	h.mu.Lock()
	defer h.mu.Unlock()
	return append([]IBKRRecordedRequest(nil), h.requests...)
}

// Count returns how many recorded requests had the given method and a path ending in suffix.
func (h *IBKRAuthHandler) Count(method, suffix string) int {
	n := 0
	for _, r := range h.Requests() {
		if r.Method == method && strings.HasSuffix(strings.SplitN(r.PathQuery, "?", 2)[0], suffix) {
			n++
		}
	}
	return n
}

func (h *IBKRAuthHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	auth := r.Header.Get("Authorization")
	route := ""
	switch {
	case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, IBKRLSTPath):
		route = IBKRLSTPath
	case r.Method == http.MethodPost && strings.HasSuffix(r.URL.Path, IBKRInitPath):
		route = IBKRInitPath
	}
	h.mu.Lock()
	h.requests = append(h.requests, IBKRRecordedRequest{Method: r.Method, PathQuery: r.URL.RequestURI(), Authorization: auth})
	o := h.overrides[route]
	h.mu.Unlock()

	if h.Strict && !ibkrSignatureMatchesVector(r, auth, route == IBKRLSTPath) {
		w.WriteHeader(http.StatusUnauthorized)
		return
	}
	if route == "" {
		if h.Next == nil {
			http.NotFound(w, r)
			return
		}
		h.Next.ServeHTTP(w, r)
		return
	}
	if o.Delay > 0 {
		select {
		case <-time.After(o.Delay):
		case <-r.Context().Done():
			return
		}
	}
	if o.Block != nil {
		select {
		case <-o.Block:
		case <-r.Context().Done():
			return
		}
	}
	status, body := o.Status, o.Body
	if status == 0 {
		status = http.StatusOK
	}
	if body == "" && status == http.StatusOK {
		if route == IBKRLSTPath {
			body = IBKRLSTReplyJSON(MustIBKRVectors().LSTReply.LiveSessionTokenSignature)
		} else {
			body = IBKRInitReplyJSON(true, false)
		}
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_, _ = w.Write([]byte(body))
}

// IBKRHeaderParam returns the raw (still percent-encoded) value of key in an OAuth Authorization header.
func IBKRHeaderParam(header, key string) string {
	prefix := key + `="`
	for _, part := range strings.Split(strings.TrimPrefix(header, "OAuth "), ", ") {
		if strings.HasPrefix(part, prefix) {
			return strings.TrimSuffix(strings.TrimPrefix(part, prefix), `"`)
		}
	}
	return ""
}

func ibkrSignatureMatchesVector(r *http.Request, auth string, lst bool) bool {
	v := MustIBKRVectors()
	nonce, sig := IBKRHeaderParam(auth, "oauth_nonce"), IBKRHeaderParam(auth, "oauth_signature")
	if lst {
		return nonce == v.LSTRequest.Nonce && sig == v.LSTRequest.OAuthSignature
	}
	q := r.URL.Query()
	for _, rv := range v.Requests {
		u, err := url.Parse(rv.URL)
		if err != nil || rv.Method != r.Method || rv.Nonce != nonce || u.Path != r.URL.Path || len(q) != len(rv.Params) {
			continue
		}
		match := true
		for k, val := range rv.Params {
			if q.Get(k) != val {
				match = false
			}
		}
		if match {
			return sig == rv.OAuthSignature
		}
	}
	return false
}
